getListProduct:
query getListProduct(
    $page: Int
    $perPage: Int
    $filter: ListProductFilterInput
  ) {
    listProduct(
      query: { pagination: { page: $page, perPage: $perPage }, filter: $filter }
    ) {
      ... on ListProductRes {
        currentPage
        items {
          brand {
            status
          }
          sni {
            status
          }
          tkdn {
            status
          }
          categoryType
          category {
            id
            isActive
            name
          }
          id
          images {
            id
            imageUrl
          }
          name
          prices {
            minPrice
            maxPrice
            minPriceWithTax
            maxPriceWithTax
            productWholesalePrices {
              price
            }
            selectedRegionPrice {
              price
              regionCode
            }
          }
          slug
          status
          stockAccumulation
          type
          username
          variants {
            id
            imageUrl
            isActive
            optionValues
            options
            price
            sku
            sortOrder
            stock
          }
          tax {
            ppnBmPercentage
            ppnPercentage
          }
          labels
          preOrder {
            sla
          }
          curationType
          curation {
            id
            productId
            status
            type
            details {
              curatorRoleId
              curatorRoleName
              description
              id
              notes
              productCurationId
              status
              rejectReasons {
                curationType
                description
                enum
                id
                reason
              }
            }
          }
          hasDecimalQuantity
        }
        lastPage
        perPage
        total
      }
      ... on GenericError {
        __typename
        code
        message
        reqId
      }
    }
  }

checkProductNameAvailability:
query checkProductNameAvailability($name: String!, $productID: String) {
    checkProductNameAvailability(name: $name, productID: $productID) {
      ... on ProductNameAvailability {
        __typename
        available
      }
      ... on GenericError {
        __typename
        code
        message
        reqId
      }
    }
  }

getAllProductCategoryListSeller:
query getAllProductCategoryListSeller($input: ListCategoryInput) {
    getAllProductCategory(input: $input) {
      ... on ProductCategories {
        __typename
        currentPage
        items {
          id
          name
          productType
        }
        total
        perPage
        lastPage
      }
      ... on GenericError {
        __typename
        code
        message
        reqId
      }
    }
  }

requestUploadSignedUrl:
query requestUploadSignedUrl($input: RequestUploadSignedUrlInput!) {
    requestUploadSignedUrl(input: $input) {
      ... on RequestUploadSignedUrlRes {
        identifier
        signedUrl
        expiry
        jwtToken
        publicKey
        __typename
      }
      ... on GenericError {
        __typename
        reqId
        message
        code
      }
    }
  }

createProduct:
mutation createProduct($input: CreateProductInput!) {
    createProduct(input: $input) {
      ... on Product {
        __typename
        id
        name
